import jwt
from datetime import datetime, timedelta

# Example of generating a JWT token with expiration
def generate_token(username, secret_key):
    token = jwt.encode({'username': username, 'exp': datetime.utcnow() + timedelta(hours=1)}, secret_key, algorithm='HS256')
    return token

# Example of decoding a JWT token
def decode_token(token, secret_key):
    try:
        data = jwt.decode(token, secret_key, algorithms=['HS256'])
        return data
    except jwt.ExpiredSignatureError:
        return 'Token has expired'
